        out.append({'title': '7张延迟采购单全部卡在待付款', 'detail': '预计到达日早于9月底的未完成采购单共%d张，合计金额%.2f元，已预付%.2f元，收货事件%d次，其中%d张ETA已早于9月1日仍未到货。' % (len(rows), amt, prep, recv, len(overdue)), 'evidence': {'po_count': len(rows), 'total_amount': round(amt, 2), 'prepaid_amount': round(prep, 2), 'received_event_count': recv, 'overdue_before_sep': len(overdue)}})

    stock = pick(['sku', 'product_name_en', 'stock_on_hand'])
    sold = pick(['sku', 'units_sold'])
    if stock and sold:
        sold_map = {r['sku']: float(r['units_sold']) for r in sold['rows']}
        alerts = []
        for r in stock['rows']:
            s = float(r['stock_on_hand'])
            u = sold_map.get(r['sku'], 0.0)
            days = s / (u / 30.0) if u > 0 else None
            if days is not None and days < 15:
                alerts.append((r['product_name_en'], r['sku'], s, u, days))
        if alerts:
            a = alerts[0]
            out.append({'title': '库存告警：%s仅可支撑%.1f天' % (a[0], a[4]), 'detail': '%s（%s）期末库存%.0f箱，9月销量%.0f箱，按当月日均销量仅可支撑约%.1f天，需优先补货。' % (a[0], a[1], a[2], a[3], a[4]), 'evidence': {'sku': a[1], 'stock_on_hand': a[2], 'units_sold': a[3], 'days_cover': round(a[4], 1), 'alert_count': len(alerts)}})

    return out
